"""Bounded archive stress: generated bytes only, no downloads or real datasets.

The largest forged archive is physically a few KiB. Large advertised sizes are
metadata edits, never large allocations. Symlink checks report a real platform
capability skip when the test process cannot create its own temporary link.
"""
from __future__ import annotations

import hashlib
import importlib.util
import json
from pathlib import Path
import random
import stat
import struct
import zipfile

import pytest


@pytest.fixture(scope="module")
def datasets():
    path = Path(__file__).resolve().parents[2] / "scripts" / "datasets.py"
    spec = importlib.util.spec_from_file_location("stress_archive_datasets", path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def _zip(path, contents):
    with zipfile.ZipFile(path, "w", compression=zipfile.ZIP_STORED) as archive:
        for name, body in contents:
            archive.writestr(name, body)


def _snapshot(root):
    if not root.exists():
        return {}
    return {p.relative_to(root).as_posix(): hashlib.sha256(p.read_bytes()).hexdigest()
            for p in root.rglob("*") if p.is_file() and not p.is_symlink()}


def _link(link, target, *, directory=False):
    try:
        link.symlink_to(target, target_is_directory=directory)
    except (OSError, NotImplementedError) as error:
        pytest.skip(f"Temporary symlink creation unavailable on this platform: {error}")


def test_seeded_portable_trees_roundtrip_without_input_mutation(datasets, tmp_path, stress_seed, stress_iterations):
    rng = random.Random(stress_seed ^ 0xA7C41)
    for iteration in range(stress_iterations):
        case = tmp_path / f"tree-{iteration:05d}"
        case.mkdir()
        expected = {}
        for member in range(rng.randint(1, 5)):
            directory = "/".join(f"d_{rng.randrange(12)}" for _ in range(rng.randint(0, 3)))
            name = f"{directory + '/' if directory else ''}f_{member}_{rng.getrandbits(24):06x}.bin"
            expected[name] = rng.randbytes(rng.randint(0, 384))
        archive = case / "input.zip"
        _zip(archive, expected.items())
        archive_hash = datasets.sha256(archive)
        destination = case / "output"
        datasets.safe_extract(archive, destination, max_bytes=2048)
        assert _snapshot(destination) == {name: hashlib.sha256(value).hexdigest() for name, value in expected.items()}
        mtimes = {name: (destination / name).stat().st_mtime_ns for name in expected}
        datasets.safe_extract(archive, destination, max_bytes=2048)
        assert {name: (destination / name).stat().st_mtime_ns for name in expected} == mtimes
        assert datasets.sha256(archive) == archive_hash


BAD_NAMES = ["../outside", "/absolute", "C:/drive", "C:relative", "..\\outside", "//server/share",
             "a/../../outside", "a./file", "a /file", "NUL", "nul.txt", "AUX.json", "PRN",
             "CON", "COM1", "LPT9.csv", "COM\u00b9.txt", "LPT\u00b2", "a:b", "a|b", "a?b", "a*b"]


@pytest.mark.parametrize("name", BAD_NAMES)
def test_hostile_names_rejected_before_destination_changes(datasets, tmp_path, name):
    destination = tmp_path / "destination"
    destination.mkdir()
    (destination / "existing.bin").write_bytes(b"STRESS_EXISTING_CANARY")
    archive = tmp_path / "input.zip"
    _zip(archive, [("new-before-invalid.txt", b"new"), (name, b"untrusted")])
    before, source = _snapshot(destination), archive.read_bytes()
    with pytest.raises(ValueError):
        datasets.safe_extract(archive, destination)
    assert _snapshot(destination) == before
    assert archive.read_bytes() == source
    assert not (tmp_path / "outside").exists()


def test_seeded_control_character_and_device_parser_rejection(datasets, stress_seed, stress_iterations):
    rng = random.Random(stress_seed ^ 0x1234)
    for _ in range(stress_iterations):
        control = chr(rng.randrange(32))
        for name in (f"safe/{control}payload", f"safe/COM{rng.randrange(1, 10)}.dat", f"safe/LPT{rng.randrange(1, 10)}"):
            with pytest.raises(ValueError):
                datasets.portable_path(name)


@pytest.mark.parametrize("members", [
    [("a.txt", b"one"), ("A.TXT", b"two")],
    [("a", b"one"), ("a/b", b"two")],
    [("a/b", b"one"), ("a", b"two")],
    [("a", b"one"), ("A/b", b"two")],
    [("A/b", b"one"), ("a", b"two")],
    [("a/", b""), ("a", b"two")],
])
def test_duplicate_or_file_directory_conflict_preserves_destination(datasets, tmp_path, members):
    destination = tmp_path / "destination"
    destination.mkdir()
    (destination / "keep").write_bytes(b"STRESS_CANARY")
    archive = tmp_path / "input.zip"
    _zip(archive, [("first", b"first"), *members])
    before = _snapshot(destination)
    with pytest.raises((ValueError, OSError)):
        datasets.safe_extract(archive, destination)
    assert _snapshot(destination) == before


def test_crc_failure_stages_without_committing_any_member(datasets, tmp_path):
    archive = tmp_path / "bad-crc.zip"
    _zip(archive, [("first", b"must not commit"), ("second", b"0123456789" * 10)])
    with zipfile.ZipFile(archive) as opened:
        offset = opened.getinfo("second").header_offset
    content = bytearray(archive.read_bytes())
    name_length, extra_length = struct.unpack_from("<HH", content, offset + 26)
    content[offset + 30 + name_length + extra_length + 5] ^= 0x40
    archive.write_bytes(content)
    destination = tmp_path / "destination"
    destination.mkdir()
    (destination / "keep").write_bytes(b"untouched")
    before = _snapshot(destination)
    with pytest.raises(zipfile.BadZipFile):
        datasets.safe_extract(archive, destination)
    assert _snapshot(destination) == before
    assert archive.read_bytes() == content


@pytest.mark.parametrize("conflict", ["different-file", "directory-instead-of-file", "file-instead-of-directory"])
def test_existing_user_content_conflict_never_commits_other_members(datasets, tmp_path, conflict):
    destination = tmp_path / "destination"
    destination.mkdir()
    if conflict == "directory-instead-of-file":
        (destination / "conflict").mkdir()
        (destination / "conflict" / "keep").write_bytes(b"STRESS_USER_CONTENT")
        name = "conflict"
    else:
        (destination / "conflict").write_bytes(b"STRESS_USER_CONTENT")
        name = "conflict/child" if conflict == "file-instead-of-directory" else "conflict"
    archive = tmp_path / "input.zip"
    _zip(archive, [("new-first", b"must not commit"), (name, b"different archive data")])
    before = _snapshot(destination)
    with pytest.raises(ValueError):
        datasets.safe_extract(archive, destination)
    assert _snapshot(destination) == before


def test_seeded_truncations_leave_existing_files_untouched(datasets, tmp_path, stress_seed, stress_iterations):
    rng = random.Random(stress_seed ^ 0xC2C)
    pristine = tmp_path / "pristine.zip"
    _zip(pristine, [("first", rng.randbytes(512)), ("second", rng.randbytes(384))])
    source = pristine.read_bytes()
    destination = tmp_path / "destination"
    destination.mkdir()
    (destination / "keep").write_bytes(b"untouched")
    before = _snapshot(destination)
    for index in range(stress_iterations):
        archive = tmp_path / "truncated.zip"
        truncated = source[:rng.randrange(0, len(source))]
        archive.write_bytes(truncated)
        with pytest.raises((zipfile.BadZipFile, EOFError, ValueError)):
            datasets.safe_extract(archive, destination)
        assert _snapshot(destination) == before, f"iteration={index}, seed={stress_seed}"
        assert archive.read_bytes() == truncated
    assert pristine.read_bytes() == source


def test_tiny_zip_with_huge_advertised_size_rejected_before_read(datasets, tmp_path, monkeypatch):
    archive = tmp_path / "metadata-bomb.zip"
    _zip(archive, [("tiny", b"small payload")])
    content = bytearray(archive.read_bytes())
    central = content.index(b"PK\x01\x02")
    struct.pack_into("<I", content, central + 24, 0x7FFFFFFF)
    archive.write_bytes(content)
    assert archive.stat().st_size < 1024
    def must_not_decompress(*args, **kwargs):
        pytest.fail("Oversized declared archive was opened before the size gate")
    monkeypatch.setattr(zipfile.ZipFile, "open", must_not_decompress)
    with pytest.raises(ValueError, match="size budget"):
        datasets.safe_extract(archive, tmp_path / "output", max_bytes=4096)
    assert not (tmp_path / "output").exists()
    assert archive.read_bytes() == content


def test_compressible_content_budget_uses_uncompressed_size(datasets, tmp_path):
    archive = tmp_path / "compressible.zip"
    with zipfile.ZipFile(archive, "w", compression=zipfile.ZIP_DEFLATED) as opened:
        opened.writestr("small-physical-large-logical", b"0" * 65536)
    assert archive.stat().st_size < 4096
    with pytest.raises(ValueError, match="size budget"):
        datasets.safe_extract(archive, tmp_path / "output", max_bytes=32768)
    assert not (tmp_path / "output").exists()


def test_archive_symlink_member_is_rejected_without_following(datasets, tmp_path):
    archive = tmp_path / "symlink.zip"
    info = zipfile.ZipInfo("link")
    info.create_system = 3
    info.external_attr = (stat.S_IFLNK | 0o777) << 16
    with zipfile.ZipFile(archive, "w") as opened:
        opened.writestr("first", b"must not commit")
        opened.writestr(info, "../outside")
    with pytest.raises(ValueError):
        datasets.safe_extract(archive, tmp_path / "output")
    assert not (tmp_path / "output").exists()


def test_existing_symlink_ancestor_cannot_escape_owned_destination(datasets, tmp_path):
    destination, outside = tmp_path / "destination", tmp_path / "outside"
    destination.mkdir(); outside.mkdir()
    (outside / "keep").write_bytes(b"STRESS_OUTSIDE_CANARY")
    _link(destination / "hop", outside, directory=True)
    archive = tmp_path / "input.zip"
    _zip(archive, [("hop/new", b"must not escape")])
    before = _snapshot(outside)
    with pytest.raises(ValueError):
        datasets.safe_extract(archive, destination)
    assert _snapshot(outside) == before


def test_changed_symlink_ancestor_rechecked_after_staging(datasets, tmp_path, monkeypatch):
    """Deterministic owned-directory swap, not a timing-dependent system attack."""
    destination, outside = tmp_path / "destination", tmp_path / "outside"
    destination.mkdir(); outside.mkdir()
    probe = tmp_path / "probe-link"
    _link(probe, outside, directory=True)
    probe.unlink()
    hop = destination / "hop"
    hop.mkdir()
    archive = tmp_path / "input.zip"
    _zip(archive, [("hop/new", b"STRESS_ONLY_TEMPORARY_DATA")])
    original = datasets.shutil.copyfileobj
    swapped = False
    def copy_then_swap(source, target, *args, **kwargs):
        nonlocal swapped
        result = original(source, target, *args, **kwargs)
        if not swapped:
            hop.rmdir()
            hop.symlink_to(outside, target_is_directory=True)
            swapped = True
        return result
    monkeypatch.setattr(datasets.shutil, "copyfileobj", copy_then_swap)
    with pytest.raises(ValueError, match="(?i)(escape|symlink|destination|path)"):
        datasets.safe_extract(archive, destination)
    assert swapped
    assert _snapshot(outside) == {}


def test_pack_referenced_symlink_is_rejected_not_archived_under_wrong_name(datasets, tmp_path):
    asset = tmp_path / "actual.bin"
    asset.write_bytes(b"STRESS_ASSET")
    _link(tmp_path / "alias.bin", asset)
    manifest = tmp_path / "manifest.json"
    manifest.write_text(json.dumps({"records": [{"image": "alias.bin"}]}), encoding="utf-8")
    before = _snapshot(tmp_path)
    with pytest.raises(ValueError, match="(?i)(symlink|portable|path|copy)"):
        datasets.pack([manifest], tmp_path / "output.zip")
    assert _snapshot(tmp_path) == before


@pytest.mark.parametrize("target", ["manifest.json", "image.bin"])
def test_pack_never_overwrites_inputs(datasets, tmp_path, target):
    (tmp_path / "image.bin").write_bytes(b"STRESS_IMAGE_BYTES")
    manifest = tmp_path / "manifest.json"
    manifest.write_text(json.dumps({"records": [{"image": "image.bin"}]}), encoding="utf-8")
    before = _snapshot(tmp_path)
    with pytest.raises(ValueError, match="(?i)(overwrite|source|output)"):
        datasets.pack([manifest], tmp_path / target)
    assert _snapshot(tmp_path) == before


@pytest.mark.parametrize("reference", ["assets\\image.bin", "../outside.bin", "C:drive-relative.bin", "/absolute.bin"])
def test_pack_rejects_nonportable_or_escaping_references_without_output(datasets, tmp_path, reference):
    source = tmp_path / "source"
    (source / "assets").mkdir(parents=True)
    (source / "assets" / "image.bin").write_bytes(b"STRESS_IMAGE")
    (tmp_path / "outside.bin").write_bytes(b"STRESS_SIBLING_CANARY")
    manifest = source / "manifest.json"
    manifest.write_text(json.dumps({"records": [{"image": reference}]}), encoding="utf-8")
    before = _snapshot(tmp_path)
    with pytest.raises(ValueError):
        datasets.pack([manifest], tmp_path / "output.zip")
    assert _snapshot(tmp_path) == before


def test_pack_roundtrip_is_deterministic_and_keeps_referenced_paths(datasets, tmp_path):
    source = tmp_path / "source"
    (source / "assets").mkdir(parents=True)
    for name in ("image.bin", "annotation.json", "truth.csv"):
        (source / "assets" / name).write_bytes(("STRESS_" + name).encode())
    record = {key: "assets/" + name for key, name in zip(("image", "annotation", "truth"), ("image.bin", "annotation.json", "truth.csv"))}
    manifest = source / "manifest.json"
    manifest.write_text(json.dumps({"records": [record]}), encoding="utf-8")
    before = _snapshot(source)
    one, two = tmp_path / "one.zip", tmp_path / "two.zip"
    datasets.pack([manifest], one); datasets.pack([manifest], two)
    assert one.read_bytes() == two.read_bytes()
    datasets.safe_extract(one, tmp_path / "restored")
    assert _snapshot(tmp_path / "restored") == before
    assert _snapshot(source) == before
